class Solution:
    def restoreMatrix(self, rowSum: list[int], colSum: list[int]) -> list[list[int]]:
        rows = rowSum[:]
        cols = colSum[:]
        m, n = len(rows), len(cols)
        ans = [[0] * n for _ in range(m)]
        i = j = 0
        while i < m and j < n:
            if rows[i] == 0:
                i += 1
            elif cols[j] == 0:
                j += 1
            else:
                ans[i][j] += 1
                rows[i] -= 1
                cols[j] -= 1
        return ans

