class Solution:
    def restoreMatrix(self, rowSum: list[int], colSum: list[int]) -> list[list[int]]:
        rows = rowSum[:]
        cols = colSum[:]
        m, n = len(rows), len(cols)
        ans = [[0] * n for _ in range(m)]
        for i in range(m):
            for j in range(n):
                x = min(rows[i], cols[j])
                ans[i][j] = x
                rows[i] -= x
                cols[j] -= x
        return ans

